"use strict";

/**
 * Orbit MCP server entrypoint.
 *
 * Cycle 96 direction choice:
 * - Compared build, earn, infrastructure, sustain, and grow.
 * - Selected infrastructure because the MCP bridge is an active adoption surface
 *   for the repository control plane, and its executable entrypoint should make
 *   the safety boundary obvious before clients wire it into IDEs or agents.
 *
 * Boundary: this process exposes SDK-backed read-only tools/resources. It does
 * not spend, sign, launch tokens, claim rewards, change payout routes, publish,
 * post outreach, or create external commitments. Future write or execution
 * tools require a separate approval-gated design and explicit live config.
 */

const { runStdioServer } = require("./src/server");

const repoRoot = process.env.ORBIT_REPO_ROOT || process.cwd();

runStdioServer({ repoRoot }).catch((err) => {
  process.stderr.write(`[orbit-mcp] fatal: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Orbit CLI — Query Orbit's state from the command line.
 *
 * Usage:
 *   orbit status [--repo /path/to/repo]
 *   orbit budget [--repo /path/to/repo]
 *   orbit capabilities [--repo /path/to/repo]
 *   orbit tasks [--repo /path/to/repo]
 *   orbit blocked [--repo /path/to/repo]
 *   orbit opportunities [--repo /path/to/repo] [--limit 5]
 *   orbit latest-cycle [--repo /path/to/repo]
 *   orbit health [--repo /path/to/repo]
 *   orbit files [--repo /path/to/repo]
 *
 * Cycle 481 direction choice:
 * - Compared build (scanner prototype), earn (agent passport), maintain (open
 *   CLI safety task), and infrastructure (control-plane growth).
 * - Selected maintain because removing detailed AI-budget fields from the
 *   public status command is the smallest live safety obligation and unblocks
 *   later calibration work without expanding execution authority.
 */

const { create } = require('./index');

function parseArgs(argv) {
  const args = { command: null, repo: process.cwd(), limit: 5 };
  let i = 2;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '--repo' || arg === '-r') {
      args.repo = argv[++i];
    } else if (arg === '--limit' || arg === '-l') {
      args.limit = parseInt(argv[++i], 10) || 5;
    } else if (arg === '--help' || arg === '-h') {
      args.command = 'help';
    } else if (!args.command) {
      args.command = arg;
    }
    i++;
  }
  return args;
}

function printJson(obj) {
  console.log(JSON.stringify(obj, null, 2));
}

function budgetLevel(summary) {
  if (!summary || summary.canUseAi === false) return 'exhausted';

  const dailyLimit = Number(summary.dailyBudgetUsd || 0);
  const monthlyLimit = Number(summary.monthlyBudgetUsd || 0);
  const dailyRemaining = Number(summary.dailyRemainingUsd || 0);
  const monthlyRemaining = Number(summary.monthlyRemainingUsd || 0);

  const ratios = [];
  if (dailyLimit > 0) ratios.push(dailyRemaining / dailyLimit);
  if (monthlyLimit > 0) ratios.push(monthlyRemaining / monthlyLimit);
  const lowestRatio = ratios.length ? Math.min(...ratios) : 1;

  if (lowestRatio <= 0) return 'exhausted';
  if (lowestRatio <= 0.1) return 'critical';
  if (lowestRatio <= 0.25) return 'low';
  return 'ok';
}

function publicBudgetSummary(sdk) {
  const summary = sdk.budgetSummary();
  return {
    status: budgetLevel(summary),
    canUseAi: Boolean(summary.canUseAi),
    policy: 'public_safe_status_only',
    note: 'Detailed inference spend and remaining budget amounts are intentionally omitted from CLI output.',
  };
}

function publicStatusSummary(sdk) {
  const status = sdk.quickStatus();
  return {
    cycle: status.cycle,
    born: status.born,
    lastActive: status.lastActive,
    lastStatus: status.lastStatus,
    currentLevel: status.currentLevel,
    currentLevelStatus: status.currentLevelStatus,
    activeLane: status.activeLane,
    openTaskCount: status.openTaskCount,
    completedTaskCount: status.completedTaskCount,
    aiBudget: publicBudgetSummary(sdk),
  };
}

function help() {
  console.log(`
Orbit CLI — Query Orbit's machine-readable state.

Commands:
  status          Quick status summary (cycle, level, tasks, budget status)
  budget          Public-safe AI-call budget status only
  capabilities    Active and planned capabilities
  tasks           Open and blocked tasks
  blocked         Wallet and external action restrictions
  opportunities   Top earning opportunities by score
  latest-cycle    Most recent cycle note
  health          Verify that expected files exist and are parseable
  files           List all machine-readable file paths

Options:
  --repo, -r      Path to Orbit repo (default: current directory)
  --limit, -l     Number of items to show (default: 5)
  --help, -h      Show this help message

Safety:
  Budget output is intentionally limited to ok/low/critical/exhausted style
  status. Do not publish detailed inference-spend figures, remaining budget
  amounts, provider routes, billing routes, or private operational details.
`.trim());
}

function main() {
  const args = parseArgs(process.argv);

  if (args.command === 'help' || !args.command) {
    help();
    process.exit(args.command ? 0 : 1);
  }

  const sdk = create(args.repo);

  switch (args.command) {
    case 'status':
      printJson(publicStatusSummary(sdk));
      break;

    case 'budget':
      printJson(publicBudgetSummary(sdk));
      break;

    case 'capabilities': {
      const caps = sdk.getCapabilities();
      printJson({
        active: caps.active.map(c => ({ id: c.id, name: c.name, mode: c.mode })),
        planned: caps.planned.map(c => ({ id: c.id, name: c.name, mode: c.mode })),
      });
      break;
    }

    case 'tasks':
      printJson(sdk.getOpenTasks());
      break;

    case 'blocked':
      printJson(sdk.getBlockedActions());
      break;

    case 'opportunities': {
      const opps = sdk.getTopOpportunities(args.limit);
      printJson(opps.map(o => ({
        id: o.id,
        title: o.title,
        score: o.driverAdjustedScore || o.score,
        status: o.status,
        risk: o.risk,
        approvalRequired: o.approvalRequired,
      })));
      break;
    }

    case 'latest-cycle':
      printJson(sdk.getLatestCycle());
      break;

    case 'health':
      printJson(sdk.healthCheck());
      break;

    case 'files':
      printJson(sdk.getFileList());
      break;

    default:
      console.error(`Unknown command: ${args.command}`);
      help();
      process.exit(1);
  }
}

main();

#!/usr/bin/env node
"use strict";

/**
 * AI Budget Ledger — CLI
 *
 * Commands: create, record, summarize, check
 * Zero external dependencies.
 *
 * Cycle 94 direction choice:
 * - Compared build, infrastructure, earn, sustain, and grow.
 * - Selected build/infrastructure because toolkit CLIs are adoption surfaces and
 *   the budget ledger needed to expose only public-safe budget status, not
 *   detailed inference spend, remaining amounts, provider routes, or billing
 *   details. This keeps the repo-local prototype useful without adding wallet,
 *   token, publishing, outreach, or external-commitment behavior.
 */

const { createLedger, record, checkBudget, summarize } = require("./ledger");
const { save, load } = require("./persist");

// ---------------------------------------------------------------------------
// Arg parsing (minimal, zero-dep)
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = { _: [], flags: {} };
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === "--json" || token === "-j") {
      args.flags.json = true;
    } else if (token === "--help" || token === "-h") {
      args.flags.help = true;
    } else if (token.startsWith("--")) {
      const key = token.replace(/^--/, "").replace(/-([a-z])/g, (_, c) => c.toUpperCase());
      const next = argv[i + 1];
      if (next && !next.startsWith("--")) {
        args.flags[key] = next;
        i++;
      } else {
        args.flags[key] = true;
      }
    } else {
      args._.push(token);
    }
  }
  return args;
}

function num(val, fallback = 0) {
  const n = Number(val);
  return Number.isFinite(n) ? n : fallback;
}

function levelFromRemaining(remaining, limit) {
  if (remaining === Infinity || !Number.isFinite(remaining) || !limit) return "ok";
  if (remaining <= 0) return "exhausted";
  const ratio = remaining / limit;
  if (ratio <= 0.1) return "critical";
  if (ratio <= 0.25) return "low";
  return "ok";
}

function mostSevereLevel(levels) {
  const order = ["ok", "low", "critical", "exhausted"];
  return levels.reduce((worst, level) => (order.indexOf(level) > order.indexOf(worst) ? level : worst), "ok");
}

function publicSummary(summary) {
  const todayLevel = levelFromRemaining(summary.today.remaining, summary.today.limit);
  const monthLevel = levelFromRemaining(summary.month.remaining, summary.month.limit);
  return {
    ok: true,
    policy: "public_safe_status_only",
    budgetStatus: mostSevereLevel([todayLevel, monthLevel]),
    todayStatus: todayLevel,
    monthStatus: monthLevel,
    entryCount: summary.entryCount,
    note: "Detailed inference spend, budget amounts, remaining amounts, provider routes, and billing routes are intentionally omitted from CLI output.",
  };
}

function publicCheck(result) {
  const dailyLimit = result.dailyRemaining === Infinity ? null : result.dailyRemaining + result.estimatedCost;
  const monthlyLimit = result.monthlyRemaining === Infinity ? null : result.monthlyRemaining + result.estimatedCost;
  const dailyLevel = levelFromRemaining(result.dailyRemaining, dailyLimit);
  const monthlyLevel = levelFromRemaining(result.monthlyRemaining, monthlyLimit);
  return {
    ok: result.allowed,
    allowed: result.allowed,
    policy: "public_safe_status_only",
    budgetStatus: result.allowed ? mostSevereLevel([dailyLevel, monthlyLevel]) : "exhausted",
    reason: result.allowed ? undefined : result.reason,
    note: "Detailed inference spend, budget amounts, remaining amounts, provider routes, and billing routes are intentionally omitted from CLI output.",
  };
}

function printPublicResult(command, result, json) {
  let safeResult = result;
  if (result.summary) {
    safeResult = { ...result, summary: publicSummary(result.summary) };
  }
  if (result.allowed !== undefined) {
    safeResult = publicCheck(result);
  }
  if (result.ledger) {
    safeResult = {
      ok: result.ok,
      message: result.message,
      policy: "public_safe_status_only",
      note: "Ledger details are written to the requested local path but omitted from CLI output.",
    };
  }
  if (result.entry) {
    safeResult = {
      ok: result.ok,
      message: result.message,
      summary: result.summary ? publicSummary(result.summary) : undefined,
      policy: "public_safe_status_only",
      note: "Recorded entry details are omitted from CLI output to avoid publishing inference spend or route details.",
    };
  }

  if (json) {
    console.log(JSON.stringify(safeResult, null, 2));
    return;
  }

  if (safeResult.message) console.log(safeResult.message);
  if (safeResult.summary) {
    const s = safeResult.summary;
    console.log(`\n--- Budget Status ---`);
    console.log(`Status:  ${s.budgetStatus}`);
    console.log(`Today:   ${s.todayStatus}`);
    console.log(`Month:   ${s.monthStatus}`);
    console.log(`Entries: ${s.entryCount}`);
    console.log(`Note:    ${s.note}`);
  } else if (command === "check") {
    console.log(`\nBudget: ${safeResult.allowed ? "OK" : "EXCEEDED"}`);
    console.log(`Status: ${safeResult.budgetStatus}`);
    if (!safeResult.allowed && safeResult.reason) {
      console.log(`Reason: ${safeResult.reason}`);
    }
    console.log(`Note: ${safeResult.note}`);
  } else if (safeResult.note) {
    console.log(`Note: ${safeResult.note}`);
  }
}

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------

function cmdCreate(ledgerPath, flags) {
  const ledger = createLedger({
    dailyBudgetUsd: num(flags.dailyBudget),
    monthlyBudgetUsd: num(flags.monthlyBudget),
    inputUsdPerMillion: num(flags.inputPrice),
    outputUsdPerMillion: num(flags.outputPrice),
  });
  save(ledgerPath, ledger);
  return { ok: true, message: `Ledger created at ${ledgerPath}`, ledger };
}

function cmdRecord(ledgerPath, flags) {
  const defaults = createLedger({
    dailyBudgetUsd: 5,
    monthlyBudgetUsd: 100,
    inputUsdPerMillion: 0.15,
    outputUsdPerMillion: 0.6,
  });
  const ledger = load(ledgerPath, defaults);

  const usage = {
    promptTokens: num(flags.promptTokens),
    completionTokens: num(flags.completionTokens),
    note: flags.note || "",
    route: flags.route || "",
  };

  const entry = record(ledger, usage);
  save(ledgerPath, ledger);
  return { ok: true, message: "Entry recorded", entry, summary: summarize(ledger) };
}

function cmdSummarize(ledgerPath) {
  const defaults = createLedger({
    dailyBudgetUsd: 5,
    monthlyBudgetUsd: 100,
    inputUsdPerMillion: 0.15,
    outputUsdPerMillion: 0.6,
  });
  const ledger = load(ledgerPath, defaults);
  const summary = summarize(ledger);
  return { ok: true, summary };
}

function cmdCheck(ledgerPath, flags) {
  const defaults = createLedger({
    dailyBudgetUsd: 5,
    monthlyBudgetUsd: 100,
    inputUsdPerMillion: 0.15,
    outputUsdPerMillion: 0.6,
  });
  const ledger = load(ledgerPath, defaults);

  const usage = {
    promptTokens: num(flags.promptTokens),
    completionTokens: num(flags.completionTokens),
  };

  const result = checkBudget(ledger, usage);
  return { ok: result.allowed, ...result };
}

// ---------------------------------------------------------------------------
// Help
// ---------------------------------------------------------------------------

function printHelp() {
  console.log(`
AI Budget Ledger — track AI API costs and enforce budgets locally

Usage:
  ai-budget create <path>     [options]   Create a new ledger file
  ai-budget record <path>     [options]   Record a usage entry
  ai-budget summarize <path>              Show public-safe budget status
  ai-budget check <path>      [options]   Check budget before a call

Create options:
  --daily-budget N      Daily budget limit in USD
  --monthly-budget N    Monthly budget limit in USD
  --input-price N       Cost per million input tokens (USD)
  --output-price N      Cost per million ou
